# -*- coding: utf-8 -*-
"""The LocalSshConnection Module mock creates and controls SSH Connections

:copyright: Nokia
:author: leo
:contact: leo.y.wang@nokia.com
"""
import logging
import subprocess
import os
import time


class LocalSshConnection(object):

    def __init__(self):
        self._log = logging.getLogger(__name__)
        logging.basicConfig()
        self._log.setLevel(logging.DEBUG)
        self.pid = None
        self.f_stdout = None
        self.f_stderr = None
        self.cli_mock_tool_stdout_name = "client_mock_stdout_{}.log".format(
            time.time())
        self.cli_mock_tool_stderr_name = "client_mock_stderr_{}.log".format(
            time.time())
        pass

    def login(self):
        """ log in.
        """
        self._log.info("clinet log in")
        pass

    def execute(self, command):
        """ Execute command on locally.

        :param String command: command string
        """
        f_stdout = open(
            "{sep}tmp{sep}{}".format(
                "client_mock.out",
                sep=os.sep),
            'w')
        f_stderr = open(
            "{sep}tmp{sep}{}".format(
                "client_mock.err",
                sep=os.sep),
            'w')
        self._log.debug("executed command is: %s" % command)
        pid = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=f_stdout,
            stderr=f_stderr,
            shell=True)
        pid.wait()
        ret = pid.poll()
        # retcode = 0 if not ret else ret
        if ret is not None:
            retcode = ret
        else:
            retcode = -1
        # pid.kill()
        f_stdout.close()
        f_stderr.close()
        f_stdout = open(
            "{sep}tmp{sep}{}".format(
                "client_mock.out",
                sep=os.sep),
            'r')
        f_stderr = open(
            "{sep}tmp{sep}{}".format(
                "client_mock.err",
                sep=os.sep),
            'r')
        stdout_ret = f_stdout.read()
        stderr_ret = f_stderr.read()
        f_stdout.close()
        f_stderr.close()
        return stdout_ret, stderr_ret, retcode

    def write(self, text):
        """ Write text locally.

        :param String text: text string
        """
        self.begin = time.time()
        self._log.debug("write:{}".format(text))
        self.f_stdout = open(
            "{sep}tmp{sep}{}".format(
                self.cli_mock_tool_stdout_name,
                sep=os.sep),
            'w')
        self.f_stderr = open(
            "{sep}tmp{sep}{}".format(
                self.cli_mock_tool_stderr_name,
                sep=os.sep),
            'w')
        if not self.pid:
            self.pid = subprocess.Popen(
                text,
                stdin=subprocess.PIPE,
                stdout=self.f_stdout,
                stderr=self.f_stderr,
                shell=True)
            self._log.debug("pid:{}".format(self.pid))
        else:
            self._log.debug("write text {} to process".format(text))
            self.pid.stdin.write(text)

    def read_until_regexp(self, expect, timeout=60):
        """ Read until expect matches output.

        :param String expect: read until expect
        :param Integer timeout: read until timeout (default is 60)
        """
        ret = ""
        tag = False
        now = time.time()
        while int(now - self.begin) <= timeout:
            f_stdout = open("{sep}tmp{sep}{}".format(self.cli_mock_tool_stdout_name, sep=os.sep), 'r')
            ret = f_stdout.readlines()
            for line in ret:
                text = line
                self._log.debug("pid {} stdout:{}".format(self.pid.pid, text))
                if expect in text:
                    f_stdout.close()
                    tag = True
                    break
            f_stdout.close()
            if tag or ("$" in expect and self.pid.poll() is not None):
                ret = str(ret) + "$ "
                return ret
            now = time.time()
            time.sleep(1)

        self._log.error("can not read {} in {} sec!".format(expect, timeout))
        f_stderr = open("{sep}tmp{sep}{}".format(self.cli_mock_tool_stderr_name, sep=os.sep), 'r')
        ret = f_stderr.read()
        self._log.error("stderr:{}".format(ret))
        f_stderr.close()
        raise Exception

    def get_file(self, src, destination):
        """ Get file locally.

        :param String src: source file
        :param String destination: destination file
        """
        import shutil
        shutil.copy2(src, destination)

    def close(self):
        """ Close.
        """
        if self.pid:
            try:
                self.pid.kill()
                os.remove("/tmp/{}".format(self.cli_mock_tool_stdout_name))
                os.remove("/tmp/{}".format(self.cli_mock_tool_stderr_name))
            except Exception as _err:
                pass
        if self.f_stdout:
            self.f_stdout.close()
        if self.f_stderr:
            self.f_stderr.close()

    def read(self):
        """ Read all output locally.
        """
        f_stdout = open(
            "{sep}tmp{sep}{}".format(
                self.cli_mock_tool_stdout_name,
                sep=os.sep),
            'r')
        f_stderr = open(
            "{sep}tmp{sep}{}".format(
                self.cli_mock_tool_stderr_name,
                sep=os.sep),
            'r')
        stdout_ret = f_stdout.read()
        stderr_ret = f_stderr.read()
        f_stdout.close()
        f_stderr.close()
        return stdout_ret, stderr_ret

    def put_file(self, src, destination):
        """ Put file locally.

        :param String src: source file
        :param String destination: destination file
        """
        import shutil
        shutil.copy2(src, destination)
